Add({
	id = "temple-of-atal-hakkar",
	title = "Temple of Atal'Hakkar",
	aliases = { "The Temple of Atal'Hakkar", "Sunken Temple", "the Sunken Temple", "Atal'Hakkar" },
	parent = "swamp-of-sorrows",
